  trial: {company: "Cloudflare", product: "Studyboard's Free AI Trial", host: (() => { try { return new URL(AI_TRIAL).host; } catch(e) { return "Studyboard's trial server"; } })(), policy: "https://www.cloudflare.com/privacypolicy/"}
