/* Theme artwork */
const skinOf = id => SKINS.find(x => x.id === id);
const isDarkNow = () => { const t = document.documentElement.getAttribute("data-theme"); return t === "dark" || (t !== "light" && !!(window.matchMedia && matchMedia("(prefers-color-scheme: dark)").matches)); };
let artSig = "";
