  const terms = {};
  const termOf = name => terms[name] = terms[name] || {name, at: 0, courses: {}, loose: []};
  allCourses().filter(c => c.archived).forEach(c => { const g = termOf(c.archived); g.at = Math.max(g.at, c.archivedAt || 0); g.courses[c.id] = {c, tasks: []}; });
