  return [m.title, m.date].filter(Boolean).join("\n") + "\n\n" + m.groups.map(g => g.name.toUpperCase() + "\n\n" + g.notes.map(n => [n.title].concat(n.body, nxMeta(n) ? ["(" + nxMeta(n) + ")"] : []).join("\n")).join("\n\n")).join("\n\n\n") + "\n";
