  const keys = [...d.grid.children].filter(n => n === d.ph || (n !== d.el && n.matches(RV_TILE))).map(n => n === d.ph ? key : n.dataset.rv);
  if (ok && d.ph.parentNode) d.ph.replaceWith(d.el); else d.ph.remove();
  d.el.style.display = "";
