        part++;
        ids.push(addDoc(IX.chunks, {g: "files", type: "chunk", fid: f.id, assetId: rec.assetId, page: pg.l ? pg.p : 0, part, label: pg.l, text: c, h: hash(name + "\n" + c)}, "", c));
