  const enabled = () => ERRCORE.decideEnabled({stored: lsGet(PREF), gpc: flag(() => navigator.globalPrivacyControl === true),
    dnt: flag(() => navigator.doNotTrack === "1" || navigator.doNotTrack === "yes" || window.doNotTrack === "1" || navigator.msDoNotTrack === "1")});
