    ui.tab = s.tab || "board"; ui.courseId = s.courseId || null; ui.courseTab = s.courseTab || ""; ui.bview = s.bview;
    if (ui.tab === "flashcards") { ui.fc = s.fc || null; ui.deckId = s.deckId || null; }
