      const g = groupOf(gid);
      toast(`Score ${shown === "anon" ? "shared anonymously" : "posted"}${g ? (shown === "anon" ? " with " : " to ") + g.name : ""}: ${right}/${total}`);
      if (gid && S.ext[gid] && S.ext[gid].ok) loadExtras(gid);
