      for (let t = start; t < end; t += 3600000) { const di = Math.round((new Date(t).setHours(0, 0, 0, 0) - today) / 864e5), h = new Date(t).getHours(); if (!(di < 7 && PF.on.has(di + ":" + h))) busy.push([t, t + 3600000]); }
