    if (/rate-limited/.test(s)) return `${P.name} was checked a lot in the last hour. Studyboard will try again later.`;
    if (/bad-url/.test(s)) return `That isn't a ${P.name} calendar link. In ${P.name}, open ${P.feedWhere}, and copy the link it shows.`;
    if (/not-calendar/.test(s)) return `${P.name} sent back something that isn't a calendar. Copy the calendar link again.`;
    if (/^Error: auth$|^auth$/.test(s)) return "Your Studyboard sign-in expired. Sign in again, then reconnect.";
    if (/too-large/.test(s)) return `That ${P.name} calendar is too big to read. Try importing a downloaded calendar file instead.`;
    if (/Error: http$|^http$|HTTP 5\d\d/.test(s)) return `${P.name} had a problem sending the calendar. Try again in a few minutes.`;
    if (/HTTP 40[134]|"status":40[134]|status 40[134]|refused/.test(s)) return `${P.name} refused the calendar link. It may have been reset. Copy a fresh one from ${P.name}, ${P.feedWhere}.`;
    if (/nofn|FunctionsHttpError|404|not found/i.test(s)) return srvSetup("Calendar link syncing on the website", "the lms-feed function") + " You can also sync from the desktop app.";
    if (/timeout/i.test(s)) return `${P.name} took too long to answer. Studyboard will try again soon.`;
    if (/fetch|network|Load failed|Failed to fetch/i.test(s)) return `Couldn't reach ${P.name}. Check your internet connection and try again.`;
    return `Something went wrong reading ${P.name}. Try again in a minute.`;
