    const courses = Object.assign({}, c.courses); data.courses.forEach(bc => { courses[bc.ou] = {code: bc.code || "", name: String(bc.name || "").slice(0, 120)}; });
    const had = new Set(c.newsItems.map(n => n.ou + "|" + n.id));
    const fresh = data.news.filter(n => !had.has(n.ou + "|" + n.id) && p.map[n.ou] !== "skip");
    const newsItems = data.src === "api" && c.news ? c.newsItems.filter(n => !data.synced.includes(n.ou)).concat(data.news.filter(n => p.map[n.ou] !== "skip")).sort((a, b) => String(b.date).localeCompare(String(a.date))).slice(0, 40) : c.newsItems;
