    if (!r || !r.ok) { if (r && r.needLogin) { signInAgain(); return; } toast(r && r.error === "too-large" ? `${f.name} is over 50 MB` : `Couldn't download ${f.name}. Try again.`); return; }
    const bin = atob(r.b64), buf = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
    const file = new File([buf], r.name || f.name, {type: r.type || "application/octet-stream"});
    const host = String(cfg().host || ""), made = await uploadFiles([file], {courseId: t.courseId, folderId: "other", taskId: t.id, origin: /^https:\/\//.test(host) ? host : "https://" + host});
    if (made && made.length) { const n = clone(state.tasks[taskId]); n[F] = Object.assign({}, n[F], {saved: Object.assign({}, n[F].saved || {}, {[f.id]: made[0].id})}); applyChanges([{kind: "task", id: n.id, after: n}], ""); }
