      forest_firefly: `${D(RG("fo-ff-glow", [[0, "#FFF7A0", .95], [.55, "#F0E86A", .45], [1, "#E8E06A", 0]]), LG("fo-ff-tail", [[0, "#FFFBC2"], [1, "#E8DC4A"]]))}<circle cx="32" cy="44" r="20" fill="url(#fo-ff-glow)"/><path d="M27 17Q22 8 15 6M37 17Q42 8 49 6" fill="none" ${SO}/><circle cx="15" cy="6" r="3" fill="#E8E06A" ${OL(2)}/><circle cx="49" cy="6" r="3" fill="#E8E06A" ${OL(2)}/><ellipse cx="14" cy="28" rx="11" ry="7.5" fill="#E9F7F0" opacity=".95" transform="rotate(-28 14 28)" ${SO}/><ellipse cx="50" cy="28" rx="11" ry="7.5" fill="#E9F7F0" opacity=".95" transform="rotate(28 50 28)" ${SO}/><ellipse cx="32" cy="45" rx="13" ry="12.5" fill="url(#fo-ff-tail)" ${SO}/><path d="M21 38Q32 43 43 38" fill="none" stroke="#B9AE32" stroke-width="2.2" stroke-linecap="round"/>${SHINE(26, 49, 4, 2.4)}<circle cx="32" cy="28" r="12.5" fill="#3F6B4A" ${SO}/><circle cx="27" cy="28" r="2.4" fill="#fff"/><circle cx="37" cy="28" r="2.4" fill="#fff"/><circle cx="27.4" cy="28.3" r="1.3" fill="#2B2233"/><circle cx="37.4" cy="28.3" r="1.3" fill="#2B2233"/><path d="M29.5 33q2.5 2 5 0" fill="none" stroke="#fff" stroke-width="1.8" stroke-linecap="round"/><ellipse cx="24" cy="32.5" rx="2.4" ry="1.5" fill="#FF8FA8" opacity=".8"/><ellipse cx="40" cy="32.5" rx="2.4" ry="1.5" fill="#FF8FA8" opacity=".8"/>`,
