  /* ================= LEMONADE ================= */
  const lemonSegs = (cx, cy, r, n, fill) => Array.from({length: n}, (_, i) => {
    const a0 = (i * 360 / n) * Math.PI / 180, a1 = ((i + 1) * 360 / n) * Math.PI / 180;
    return `<path d="M${cx} ${cy}L${f(cx + r * Math.cos(a0))} ${f(cy + r * Math.sin(a0))}A${r} ${r} 0 0 1 ${f(cx + r * Math.cos(a1))} ${f(cy + r * Math.sin(a1))}Z" fill="${fill}"/>`;
  }).join("");
