  /* =================== MINT CHIP =================== */
  const chip = (x, y, r = 0, s = 1) => `<path d="M${x} ${y}l${f(4 * s)} ${f(-1.2 * s)}l${f(-.8 * s)} ${f(4 * s)}z" fill="#4A2E1A" stroke="#4A2E1A" stroke-width="1" stroke-linejoin="round" transform="rotate(${r} ${x} ${y})"/>`;
