  const mouth = (x, y, w = 2, sw = 1.8) => `<path d="M${x - w} ${y}q${w} ${w * .85} ${w * 2} 0" fill="none" stroke="${O}" stroke-width="${sw}" stroke-linecap="round"/>`;
