    q("#phGL").addEventListener("input", e => { d.gl = +e.target.value; queue(); });
    q("#phFxReset").addEventListener("click", () => { const z = clean({id: d.id, sw: d.sw, wt: d.wt}); d.ac = ""; d.ai = -1; d.gr = z.gr; d.tn = z.tn; d.gl = 0; d.vg = 0; queue(); });
