  const rosette = (tier, t, tail) => { let sc = ""; for (let i = 0; i < 14; i++) { const a = i / 14 * Math.PI * 2; sc += `<circle cx="${(32 + 18.5 * Math.cos(a)).toFixed(2)}" cy="${(27 + 18.5 * Math.sin(a)).toFixed(2)}" r="5.2"/>`; }
    return `${tierDef(tier, "rs")}<path d="M22 38l-7 22 8-4.5 5 7 4.5-21z" fill="${tail}" ${S(2.2)}/><path d="M42 38l7 22-8-4.5-5 7-4.5-21z" fill="${tail}" ${S(2.2)}/><g fill="url(#rs)" ${S(2.2)}>${sc}</g><circle cx="32" cy="27" r="18.5" fill="url(#rs)"/><circle cx="32" cy="27" r="14" fill="#FFFDF6" ${S(2)}/>${txt(t, 32, 31.6, 12.5, D, 22)}${shine(24, 17, 3.6, 2)}`; };

