    evaluate({quiet: true, lab});
    sc = clone(SC());
    const old = sc.cur;
    old.e = todayISO(); old.lab = label; old.g["term-end"] = nowMin(); old.sum = summaryOf(sc, label); old.sum.st = Object.keys(old.g).length;
