    const lp = X.bq("lowpass", 3400, .5), bed = X.g(.5); X.drift(lp.frequency, 2400, 3800, 6, 16, true); X.drift(bed.gain, .38 * lv, .58 * lv, 5, 14);
    X.chain(X.stereo("pink"), X.bq("highpass", 380, .6), lp, bed, X.out);
