      const s = X.ctx.createBufferSource(); s.buffer = pops; s.playbackRate.value = X.r(.8, 1.2); const sg = X.g(X.r(.3, .55));
      s.start(t, X.ri(0, 5) * 2 / 6); s.stop(t + .25);
