    const t = e.target; if (!t || !t.closest || !t.closest(".snd-panel")) return;
    if (t.hasAttribute("data-snd-vol")) { if (E) E.master.gain.setTargetAtTime(volGain(Number(t.value)), E.ctx.currentTime, .05); }
