  const isDay = SH.kind === "day";
  const D = isDay ? m.days.find(d => d.date === SH.key) : null;
  const ws = isDay ? C.monday(SH.key) : SH.key;
  const W = m.weeks.find(w => w.start === ws);
  if (!W || (isDay && !D)) { if (dlg.open) dlg.close(); return; }
