      if (o.type === "meet" && o.label === "Office Hours") return;
      const span = o.type === "event" && o.ev && o.ev.allDay && !o.ev.repeat && o.ev.endDate && o.ev.endDate > o.ev.date;
      if (span && o.key !== o.ev.date) return;
