  const AL = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_", AIX = {};
  for (let i = 0; i < 64; i++) AIX[AL.charCodeAt(i)] = i;
