    if (active) inp.free = freeMap(today);
    else { const sd = studyDay(new Date(now)), th = todayHours(); inp.daily = {h: dailyHours(), today: sd.date === today ? Math.min(th, sd.left / 60) : th, start: sd.start, end: sd.end}; }
